function ArcherResults({report,downloadReport}:{report:ArcherReport;downloadReport:()=>void}){return <section className="archer-report-panel"><ArcherReasoning report={report}/><ArcherResultsBody report={report} downloadReport={downloadReport}/></section>}
function ArcherEvidenceList({evidence}:{evidence?:ArcherEvidence[]}){if(!evidence?.length)return <p className="evidence-empty">No evidence details were supplied.</p>;return <ul className="evidence-list">{evidence.map((item,index)=><li key={`${item.kind}-${item.file}-${item.line}-${index}`}><span>{item.kind} · {item.strength}</span><strong>{item.mechanism}</strong>{item.symbol&&<code>{item.symbol}</code>}<small>{item.file}:{item.line}{item.handler?` · ${item.handler}`:''}</small></li>)}</ul>}
function ArcherRouteReferenceView({route,flagged=false}:{route:ArcherRouteReference;flagged?:boolean}){return <article className={`reasoning-route-card${flagged?' flagged':''}`}><div className="reasoning-route-heading"><div><b>{route.method}</b><strong>{route.path}</strong></div>{flagged&&<span className="route-flag">TRIGGERED FINDING</span>}<small>{route.handler||'Handler unavailable'} · {route.file}:{route.line}</small><span className={route.authorized?'route-auth-status':'route-auth-status absent'}>{route.authorized?'AUTHORIZATION EVIDENCE':'NO RECOGNIZED AUTHORIZATION'}</span></div><ArcherEvidenceList evidence={route.authorization}/></article>}
function ArcherReasoning({report}:{report:ArcherReport}){const groups=report.peer_groups||[],invariants=report.invariants||[],details=report.finding_details||[];if(!groups.length&&!invariants.length)return null;return <section className="archer-reasoning"><div className="archer-results-heading"><div><p className="eyebrow">05 / PEER-GROUP REASONING</p><h2>Patterns in<br/><em>context.</em></h2></div><span className="muted">{groups.length} peer group{groups.length===1?'':'s'} · {invariants.length} invariant{invariants.length===1?'':'s'}</span></div><div className="reasoning-flow"><span>Routes</span><b>→</b><span>Peer groups</span><b>→</b><span>Invariants</span><b>→</b><span>Potential drift</span></div><div className="reasoning-groups">{groups.map(group=>{const groupFindings=details.filter(item=>item.peer_group_id===group.id);const invariant=invariants.find(item=>item.peer_group_id===group.id)||groupFindings[0]?.invariant;return <details className="reasoning-group" key={group.id}><summary><span>{group.id}</span><strong>{group.description}</strong><small>{group.routes.length} routes</small></summary><div className="reasoning-group-body">{invariant?<div className="reasoning-invariant"><span>INFERRED AUTHORIZATION INVARIANT · {invariant.strength}</span><p>{invariant.description}</p><b>{invariant.routes_with_authorization} of {invariant.total_routes} routes have recognized authorization evidence · {invariant.routes_without_authorization} without</b>{invariant.evidence_patterns?.length>0&&<div className="invariant-patterns"><small>Observed peer patterns</small>{invariant.evidence_patterns.map(pattern=><code key={pattern}>{pattern}</code>)}</div>}</div>:<p className="muted">No invariant details were supplied for this peer group.</p>}<div className="reasoning-routes">{group.routes.map((route,index)=>{const flagged=groupFindings.some(item=>item.suspicious_route.method===route.method&&item.suspicious_route.path===route.path&&item.suspicious_route.file===route.file&&item.suspicious_route.line===route.line);return <ArcherRouteReferenceView key={`${route.file}-${route.line}-${index}`} route={route} flagged={flagged}/>})}</div></div></details>})}</div></section>}
function ArcherReasoningEmpty({report}:{report:ArcherReport}){const routeCount=report.routes?.length,parseErrorCount=report.parse_errors?.length||0;const title=routeCount===0?'No routes were extracted.':routeCount===undefined?'Route inventory is unavailable.':'No peer-group invariant was inferred.';const description=routeCount===0?`The engine scanned ${report.files_scanned} Rust file${report.files_scanned===1?'':'s'} and found no Actix-Web route candidates.${parseErrorCount?` ${parseErrorCount} file${parseErrorCount===1?'':'s'} could not be parsed.`:' No parse errors were reported.'}`:routeCount===undefined?'This report did not include route inventory data, so peer-group reasoning cannot be assessed.':`The engine extracted ${routeCount} route candidates but formed no qualifying peer group. This does not establish whether those routes are protected.`;return <section className="reasoning-empty"><span>05 / REASONING</span><strong>{title}</strong><p>{description}</p></section>}
import React, { createContext, useContext, useEffect, useRef, useState } from 'react'
