const fallbackMembers: Member[] = Object.entries(fallbackContent.roles).map(([name, role]) => ({ name, role, slug: memberSlug(name), skills: [], skill_groups: {}, archer_focus: [] })).sort((a, b) => a.name.localeCompare(b.name))
function groupedSkills(member: Member): SkillGroups {
  const groups = member.skill_groups || {}
  if (Object.keys(groups).length && !('Core skills' in groups)) return groups
  const skills = member.skills.length ? member.skills : (groups['Core skills'] || [])
  const categories: SkillGroups = {}
  const add = (category:string, skill:string) => (categories[category] ||= []).push(skill)
  skills.forEach(skill => /react|tailwind|css|typescript|javascript|ui/i.test(skill) ? add('Frontend', skill) : /python|postgres|database|api|fastapi/i.test(skill) ? add('Backend & data', skill) : /system design|architecture|security|performance/i.test(skill) ? add('Architecture', skill) : add('Tools & practices', skill))
  return categories
}
type Asset = {id:number;relative_path:string;file_name:string;content_type:string;size_bytes:number;file_url:string;download_url?:string}
type Presentation = { id:number; title:string; slug:string; version:string; presentation_date:string; authors:string; change_summary:string; file_name:string; published:boolean; created_by:string; file_url?:string; assets?:Asset[] }
type ArcherEvidence = {kind:string;mechanism:string;symbol?:string|null;file:string;line:number;handler?:string|null;strength:string}
type ArcherRoute = {method:string;path:string;scope_prefix:string;handler?:string|null;authorization:ArcherEvidence[];line:number;file:string}
type ArcherRouteReference = {method:string;path:string;handler?:string|null;file:string;line:number;authorized:boolean;authorization:ArcherEvidence[]}
type ArcherPeerGroup = {id:string;description:string;routes:ArcherRouteReference[]}
type ArcherInvariant = {peer_group_id:string;description:string;total_routes:number;routes_with_authorization:number;routes_without_authorization:number;evidence_patterns:string[];strength:string}
type ArcherFinding = {peer_group_id:string;invariant:ArcherInvariant;suspicious_route:ArcherRouteReference;suspicious_route_evidence:ArcherEvidence[];authorized_peer_routes:ArcherRouteReference[]}
type ArcherReport = {files_scanned:number;parse_errors?:string[];routes?:ArcherRoute[];peer_groups?:ArcherPeerGroup[];invariants?:ArcherInvariant[];findings?:string[];finding_details?:ArcherFinding[];repository_files?:number;repository_bytes?:number}
const ContentContext = createContext<Content>(fallbackContent)
const useContent = () => useContext(ContentContext)
const ApiStatusContext = createContext<{error:string; setError:React.Dispatch<React.SetStateAction<string>>}>({error:'',setError:()=>{}})
const useApiStatus = () => useContext(ApiStatusContext)
const AuthContext = createContext<{user:User|null; setUser:React.Dispatch<React.SetStateAction<User|null>>}>({user:null,setUser:()=>{}})
const useAuth = () => useContext(AuthContext)
const auth = (): Record<string, string> => { const token = localStorage.getItem('token'); return token ? {Authorization:`Bearer ${token}`} : {} }
async function request(path:string, options:RequestInit={}) {
  const response=await fetch(API+path,{...options,headers:{...auth(),...options.headers}})
  if(!response.ok){const error=await response.json().catch(()=>({detail:'Request failed'}));throw new Error(error.detail||'Request failed')}
  if(response.status===204)return null
  const body=await response.text()
  return body?JSON.parse(body):null
}
function ContentProvider({children}:{children:React.ReactNode}) { const [content,setContent]=useState<Content>(fallbackContent),[error,setError]=useState(''); useEffect(()=>{request('/site-content').then(setContent).catch(reason=>{if(usingConfiguredApi)setError(`Live project content is unavailable: ${(reason as Error).message}`)})},[]); return <ApiStatusContext.Provider value={{error,setError}}><ContentContext.Provider value={content}>{children}</ContentContext.Provider></ApiStatusContext.Provider> }
function AuthProvider({children}:{children:React.ReactNode}) { const [user,setUser]=useState<User|null>(null); useEffect(()=>{if(localStorage.getItem('token'))request('/auth/me').then(setUser).catch(()=>localStorage.removeItem('token'))},[]); return <AuthContext.Provider value={{user,setUser}}>{children}</AuthContext.Provider> }
const homeSections = [{id:'project', label:'Project', number:'01'}, {id:'team', label:'Team', number:'02'}, {id:'archive', label:'Archive', number:'03'}]
function Layout({children}:{children:React.ReactNode}) {
  const content=useContent(), {user}=useAuth(), {error}=useApiStatus(), location=useLocation()
  const [activeSection,setActiveSection]=useState('')
  const isHome=location.pathname==='/'
  useEffect(()=>{
    if(!isHome){setActiveSection('');return}
    const hashTarget=location.hash.replace('#','')
    if(hashTarget){requestAnimationFrame(()=>document.getElementById(hashTarget)?.scrollIntoView({behavior:'smooth',block:'start'}))}
    const sections=homeSections.map(({id})=>document.getElementById(id)).filter((section):section is HTMLElement=>Boolean(section))
    const observer=new IntersectionObserver(entries=>{
      const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0]
      if(visible)setActiveSection(visible.target.id)
    },{rootMargin:'-28% 0px -58% 0px',threshold:[.05,.2,.45,.7]})
    sections.forEach(section=>observer.observe(section))
    return ()=>observer.disconnect()
  },[isHome,location.hash])
  return <><header><Link aria-label="Archer home" className="home-icon" to="/">⌂</Link><nav className="site-nav" aria-label="Site sections">{!staticDemoMode&&<Link className={location.pathname==='/use'?'active':''} to="/use"><span>00</span>Use Archer</Link>}{homeSections.map(section=>isHome?<a href={`#${section.id}`} className={activeSection===section.id?'active':''} onClick={()=>setActiveSection(section.id)} key={section.id}><span>{section.number}</span>{section.label}</a>:<Link to={`/#${section.id}`} key={section.id}><span>{section.number}</span>{section.label}</Link>)}</nav><div className="header-account">{user?<Link className="account-link" to="/admin">{user.display_name.split(' ')[0]}</Link>:!staticDemoMode&&<Link className="nav-capsule" to="/login">Log in <span>→</span></Link>}</div></header>{error&&<p className="api-status error" role="alert">{error}</p>}<main>{children}</main><footer><span>{content.projectName} / Software Engineering Lab</span><span>Versioned project archive</span></footer></>
}
function Info({title,children}:{title:string;children:React.ReactNode}){return <article className="fact"><span>{title}</span><p>{children}</p></article>}
function BackgroundLeaves(){return <div className="decorative-leaves" aria-hidden="true">{['leaf-one','leaf-two','leaf-three','leaf-four','leaf-five','leaf-six'].map(name=><svg className={`background-leaf ${name}`} viewBox="0 0 24 24" key={name}><path d="M12 1.5 14.2 8l5.8-2.6-2.8 6 5.3 2.4-5.9 1.2 1.7 6.4-5.3-3.6-4.6 4.7.4-6.7-6.5.5 4.4-5-4.2-4.9L9.8 8 12 1.5Z"/></svg>)}</div>}
function Home(){ const copy=useContent(),{setError}=useApiStatus(); const [items,setItems]=useState<Presentation[]>([]); useEffect(()=>{request('/presentations').then(setItems).catch(reason=>{if(usingConfiguredApi)setError(`Live archive data is unavailable: ${(reason as Error).message}`)})},[setError]); return <><BackgroundLeaves/><section className="hero"><div className="hero-copy"><p className="eyebrow">SOFTWARE ENGINEERING LAB · 2026</p><h1>{copy.projectName}<i>.</i></h1><div className="hero-summary"><span>01 / PUBLIC RECORD</span><div aria-label="What Archer brings together"><strong>Plan.</strong><strong>People.</strong><strong>Progress.</strong></div><p>{copy.tagline}</p></div><div className="hero-actions"><a className="button" href="#archive">Browse archive <span>↓</span></a><Link className="text-link" to="/planning-v1">Planning V1</Link></div></div><aside className="hero-index" aria-label="Archer principles"><span>ARCHER / EDITION 01</span><strong>Living archive.</strong><strong>Public by design.</strong><strong>Progress, preserved.</strong></aside></section><section className="manifesto"><span>01</span><h2>Built in public.<br/>Tracked <em>properly.</em></h2><p>Every deliverable gets a permanent home, its own version, and a complete history.</p></section><section className="home-facts" aria-label="Why Archer exists"><article className="home-problem"><p className="eyebrow">THE PROBLEM</p><h2>Project work<br/>loses its <em>context.</em></h2><p>Student projects create far more than a final product — plans, iterations, feedback and decisions. But most of it gets scattered and is hard to trace later.</p></article><div className="home-fact-stack"><article className="home-objectives"><p className="eyebrow">OUR OBJECTIVES</p><ol>{['Preserve the full project journey.','Organize outputs and track evolution.','Make team work and contribution visible.'].map((objective,index)=><li key={objective}><span>{String(index+1).padStart(2,'0')}</span><p>{objective}</p></li>)}</ol></article><div className="home-fact-pair"><article><p className="eyebrow">USERS</p><p>Student teams, collaborators, and instructors.</p></article><article><p className="eyebrow">CORE</p><p>Versioned work, structured archives, and a public record.</p></article></div></div></section><HomeProject/><HomeTeam/><HomeArchive items={items}/></> }
function HomeProject(){const system=[['Brief','Problem, scope, and objectives.'],['People','Team, roles, and contributions.'],['Progress','Plans, iterations, and current status.'],['Archive','Versioned work and past releases.']];return <section className="home-section home-project" id="project" data-home-section="project"><div className="home-editorial-grid"><div className="home-editorial-copy"><p className="eyebrow">01 / PROJECT</p><h2>All the context.<br/><em>One clear place.</em></h2><p className="lede">A living view of the project — its purpose, people, progress, and complete history.</p></div><div className="home-overview-canvas"><div className="overview-canvas-heading"><div><p className="eyebrow">CURRENT PROJECT</p><h3>Archer / Overview</h3><p>A continuously evolving project record.</p></div><Link className="button secondary" to="/project">Explore the project <span>↗</span></Link></div><ol className="overview-cards">{system.map(([title,description],index)=><li key={title}><span>0{index+1}</span><h4>{title}</h4><p>{description}</p></li>)}</ol></div></div></section>}
const featuredTeamOrder=['Divyansh Tripathi','Lavish Gambhir','Mehardeep Singh','Vidit Gupta']
const orderedFeaturedMembers=(members:Member[])=>[...members].sort((a,b)=>{const aIndex=featuredTeamOrder.indexOf(a.name),bIndex=featuredTeamOrder.indexOf(b.name);return (aIndex<0?featuredTeamOrder.length:aIndex)-(bIndex<0?featuredTeamOrder.length:bIndex)||a.name.localeCompare(b.name)})
