  useEffect(()=>{request(`/team/${slug}`).then(setMember).catch(reason=>{if(!fallbackMember)setError((reason as Error).message)})},[slug,fallbackMember])
  useEffect(()=>setImageUnavailable(false),[member?.avatar_url])
  if(error)return <section className="page"><h1>Member not found.</h1></section>
