    const ArcherResultsContent = ({report,downloadReport}:{report:ArcherReport;downloadReport:()=>void})=><section className="archer-report-panel"><ArcherResultsBody report={report} downloadReport={downloadReport}/>{!report.peer_groups?.length&&!report.invariants?.length&&!report.finding_details?.length&&<ArcherReasoningEmpty report={report}/>}<ArcherReasoning report={report}/></section>
