  const filePath=(file:File)=>(file as File & {webkitRelativePath?:string}).webkitRelativePath||file.name
  const isAnalysisFile=(file:File)=>{const path=filePath(file).replaceAll('\\','/');if(/(^|\/)(target|node_modules|\.venv|venv|dist|build|__pycache__)(\/|$)/.test(path))return false;return ['.rs','.toml','.lock','.md','.txt','.json','.yaml','.yml'].some(extension=>file.name.toLowerCase().endsWith(extension))}
