  useEffect(()=>{if(!open)return;const onKeyDown=(event:KeyboardEvent)=>{const next=['ArrowRight',' ','Spacebar','PageDown'].includes(event.key),previous=['ArrowLeft','PageUp'].includes(event.key);if(next||previous||['Escape','Home','End'].includes(event.key))event.preventDefault();if(event.key==='Escape'){onClose();return}if(!pageCount)return;if(next)setPage(current=>Math.min(pageCount,current+1));else if(previous)setPage(current=>Math.max(1,current-1));else if(event.key==='Home')setPage(1);else if(event.key==='End')setPage(pageCount)};window.addEventListener('keydown',onKeyDown);rootRef.current?.focus();return()=>window.removeEventListener('keydown',onKeyDown)},[open,onClose,pageCount,rootRef])
